from harvests import Harvest, load_harvests, ROWS
from ranking import ranked_codes


def test_nine_before_ten():
    assert ranked_codes([Harvest("a", 10), Harvest("b", 9)]) == ["9", "10"]


def test_mixed_lengths():
    assert ranked_codes([Harvest("a", 100), Harvest("b", 25), Harvest("c", 9), Harvest("d", 1000)]) == ["9", "25", "100", "1000"]


def test_stored():
    assert ranked_codes(list(load_harvests())) == [str(v) for v in sorted(v for _, v in ROWS)]


def test_codes_are_text():
    assert all(isinstance(c, str) for c in ranked_codes(list(load_harvests())))


def test_empty():
    assert ranked_codes([]) == []

